pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, address attacker, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(this) && actor != attacker);
        vm.assume(attacker != address(0) && attacker != address(this));
        vm.assume(amount > 0 && amount <= type(uint128).max);

        // Fund the contract with Ether
        vm.deal(address(c), amount);

        // Actor calls attacker contract, which internally calls withdrawAll on the target contract
        // If withdrawAll uses tx.origin, the attacker can pass the check when actor initiates the call.
        bool attackerSucceeded;
        {
            address payable target = payable(address(c));
            address payable recipient = payable(attacker);
            vm.prank(actor);
            try Attacker(attacker).attemptWithdraw(target, recipient) {
                attackerSucceeded = true;
            } catch {
                attackerSucceeded = false;
            }
        }

        // Assert that when actor != owner, attacker cannot successfully withdraw
        assertTrue(!(actor != c.owner() && attackerSucceeded));
    }
}

contract Attacker {
    function attemptWithdraw(address payable target, address payable recipient) external {
        C(target).withdrawAll(recipient);
    }
}

