pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(address caller, uint256 contractBalance, uint256 recipientAmount) public {
        // Restrict to admissible domain
        vm.assume(caller != address(this)); // non-owner
        vm.assume(contractBalance > 0);     // we need a positive balance to observe a potential decrease
        // Fund the contract with some Ether
        vm.deal(address(c), contractBalance);
        // Record balance before the call
        uint256 balanceBefore = address(c).balance;
        // Attempt withdrawAll as the non-owner caller
        vm.prank(caller);
        try c.withdrawAll(address(this)) {
            // If no revert, check that the contract balance did NOT decrease
            uint256 balanceAfter = address(c).balance;
            // For the reference, this must always hold (balanceBefore == balanceAfter);
            // the mutant may cause balanceAfter == 0, failing the assertion.
            assertTrue(balanceAfter == balanceBefore);
        } catch {
            // Reference contract reverts; balance remains unchanged.
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}
